"OLAYLAR_ORTACAG_ORTADOGU:0815-08-11:0":{"b": ["Իբրահիմ բ. Մուսան գրավեց Սանան (200/815). Եմենը դուրս եկավ Աբբասյան կուսակալների ձեռքից", "49e27fe7"], "d": ["Ալիական ապստամբ Իբրահիմ բ. Մուսան, հաղթելով Մամունի ուղարկած զորամասերին, գրավեց Սանան (200/815). մինչև որ Համդավեյհ բ. Մահանը հաղթեց նրան և հռչակեց անկախություն (203/818), քաղաքը դուրս եկավ Աբբասյան խալիֆայության փաստացի կառավարումից։", "dc150649"]},
"OLAYLAR_ORTACAG_ORTADOGU:0820-06-17:0":{"b": ["Իսա բ. Յազիդ ալ-Ջալուդին վերացրեց Համդավեյհին (205/820). Սանան վերադարձավ Աբբասյան կուսակալների կառավարմանը", "167a2fb1"], "d": ["Անկախություն հռչակած Համդավեյհ բ. Մահանին վերացրեց Իսա բ. Յազիդ ալ-Ջալուդին (205/820). Սանան և շրջակայքը մինչև 232 (847) թվականը կառավարվեցին Բաղդադից ուղարկված Աբբասյան կուսակալների կողմից։ Այս թվականով ատլասում Սանայի դատարկությունը (815-820) ավարտվում է, սկսվում է Աբբասյան խալիֆայության շրջանը։", "72c4a623"]},
"OLAYLAR_ORTACAG_ORTADOGU:0833-08-09:0":{"b": ["Մամունը Բյուզանդիայի դեմ արշավանքի ժամանակ մահացավ Բեդենդունի մոտ (18 Ռաջաբ 218). նրա եղբայր Մուտասիմը դարձավ խալիֆա։", "fa3c1a4c"], "d": ["Մամունը Բյուզանդիայի դեմ արշավանքի ժամանակ մահացավ Բեդենդունի մոտ (18 Ռաջաբ 218). նրա եղբայր Մուտասիմը դարձավ խալիֆա։", "fa3c1a4c"]},
"OLAYLAR_ORTACAG_ORTADOGU:0836-01-01:0":{"b": ["Մուտասիմը հիմնեց Սամառան և խալիֆայության կենտրոնը տեղափոխեց այնտեղ։", "34873200"], "d": ["Մուտասիմը հիմնեց Սամառան և խալիֆայության կենտրոնը տեղափոխեց այնտեղ։", "34873200"]},
"OLAYLAR_ORTACAG_ORTADOGU:0838-01-01:0":{"b": ["Մուտասիմը, մտնելով Անատոլիա, պաշարեց և գրավեց Ամորիոնը", "63534eea"], "d": ["Խալիֆա Մուտասիմը 838 թ. մեծ բանակով մտավ Անատոլիա. Անկարայի վրայով շարժվելով՝ պաշարեց և գրավեց Աֆյոնի մոտ գտնվող, Անատոլիայի մեծ քաղաքներից Ամորիոնը։", "530472b7"]},
"OLAYLAR_ORTACAG_ORTADOGU:0868-09-15:0":{"b": ["Ահմեդ բ. Թուլունը որպես կուսակալի տեղակալ մտավ Եգիպտոս. դրվեցին Թուլունյանների հիմքերը", "7bfc6989"], "d": ["Ահմեդ բ. Թուլունը որպես կուսակալի տեղակալ մտավ Եգիպտոս. դրվեցին Թուլունյանների հիմքերը", "7bfc6989"]},
"OLAYLAR_ORTACAG_ORTADOGU:0870-01-01:0":{"b": ["Կառավարման կենտրոնը տեղափոխվեց նորակառույց Կատաի թաղամասի պալատ (256/870)։", "f6fd1a7f"], "d": ["Կառավարման կենտրոնը տեղափոխվեց նորակառույց Կատաի թաղամասի պալատ (256/870)։", "f6fd1a7f"]},
"OLAYLAR_ORTACAG_ORTADOGU:0870-08-29:0":{"b": ["Աղլաբյան նավատորմը վերջնականապես գրավեց Մալթան (28 Ռամադան 256)", "71f7ca41"], "d": ["Սիցիլիայի Աղլաբյան հրամանատարներից Ահմեդ բ. Օմարի հրամանատարությամբ նավատորմը վերջնականապես գրավեց Մալթան (28 Ռամադան 256 / 870 թ. օգոստոսի 29). կղզին 533 թ. ի վեր գտնվում էր Բյուզանդիայի (Արևելյան Հռոմեական) տիրապետության ներքո, այս օրվանից մահմեդական տիրապետությունը դարձավ մշտական։ Ատլասում Մալթան, Մդինան և Գոզոն այս օրվանից վերագրված են Աղլաբյաններին։", "a9aa1a35"]},
"OLAYLAR_ORTACAG_ORTADOGU:0884-01-01:0":{"b": ["Ահմեդ բ. Թուլունը մահացավ, նրան հաջորդեց որդի Խումարավեյհը (270/884)։", "cad7d779"], "d": ["Ահմեդ բ. Թուլունը մահացավ, նրան հաջորդեց որդի Խումարավեյհը (270/884)։", "cad7d779"]},
"OLAYLAR_ORTACAG_ORTADOGU:0886-12-01:0":{"b": ["Աբբասյանների հետ կնքված պայմանագրով ճանաչվեց Եգիպտոսի ինքնիշխանությունը. Սիրիան, Պաղեստինը և Ջազիրան երեսուն տարով տրվեցին Թուլունյաններին (Ռաջաբ 273 / 886 թ. դեկտեմբեր. ամսվա առաջին օրը)։", "89b24789"], "d": ["Աբբասյանների հետ կնքված պայմանագրով ճանաչվեց Եգիպտոսի ինքնիշխանությունը. Սիրիան, Պաղեստինը և Ջազիրան երեսուն տարով տրվեցին Թուլունյաններին (Ռաջաբ 273 / 886 թ. դեկտեմբեր. ամսվա առաջին օրը)։", "89b24789"]},
