"OLAYLAR_ORTACAG_ORTADOGU:0910-01-15:0":{"b": ["Աբու Աբդուլլահը Ուբայդ Ալլահ ալ-Մահդիի հետ մտավ Ռակկադա. փաստացի սկսվեց Ֆաթիմյան իմամությունը", "cf944741"], "d": ["Աբու Աբդուլլահը գրավեց Աղլաբյանների մայրաքաղաք Ռակկադան և վտարեց վերջին ամիրա Զիյադաթ Ալլահին (296/909). 29 Ռաբի աս-սանի 297-ին (910 թ. հունվարի 15) Ուբայդ Ալլահի հետ մտավ Ռակկադա։", "99f93307"]},
"OLAYLAR_ORTACAG_ORTADOGU:0915-07-17:0":{"b": ["Ուբայդ Ալլահ ալ-Մահդին հիմնեց Մահդիա քաղաքը", "f6aef126"], "d": ["Մահդին Արևելյան Իֆրիկիայի ափի թերակղզում հիմնեց Մահդիա անունով քաղաքը (303/915)։", "eccb119a"]},
"OLAYLAR_ORTACAG_ORTADOGU:0920-05-23:0":{"b": ["Մահդիան հռչակվեց Ֆաթիմյան մայրաքաղաք", "a160b592"], "d": ["Հիմնումից հինգ տարի անց Մահդիան հռչակվեց մայրաքաղաք (308/920)։", "eb88ec52"]},
"OLAYLAR_ORTACAG_ORTADOGU:0929-02-14:0":{"b": ["Ղարմաթները, գրավելով Մեքքան, Սև քարը տարան Ահսա (Լահսա). Բահրեյնի Ղարմաթյան պետությունը՝ Լահսայի տերը առաջին թվագրված վկայությամբ", "5ca42bf9"], "d": ["Իսմայիլյան Ղարմաթները (Բահրեյնի Ղարմաթյան պետությունը) 317 հիջ. / 929 թ., գրավելով Մեքքան, Սև քարը տարան Ահսա (Լահսա). սակայն այն իր տեղը դրվեց միայն քսան տարի անց։ Ատլասում Լահսան, Աբբասյան խալիֆայության տարածքում լինելով, այս առաջին թվագրված վկայությունից սկսած վերագրված է Ղարմաթներին։", "a6a3faa1"]},
"OLAYLAR_ORTACAG_ORTADOGU:0929-03-02:0":{"b": ["Աբու ալ-Հայջան մահացավ. հարստությունը բաժանվեց Մոսուլի և Հալեպի ճյուղերի, Մոսուլում առաջ եկավ Նասիր ալ-Դաուլա Հասանը", "2ecf5e83"], "d": ["Աբու ալ-Հայջան մահացավ. հարստությունը բաժանվեց Մոսուլի և Հալեպի ճյուղերի, Մոսուլում առաջ եկավ Նասիր ալ-Դաուլա Հասանը", "2ecf5e83"]},
