"OLAYLAR_ORTACAG_ORTADOGU:1102-01-01:0":{"b": ["Տրիպոլիի (Լիբանան) առջև տեղի ունեցած ճակատամարտում Ռեմոն դը Սեն-Ժիլը հաղթեց քաղաքի պաշտպաններին։", "4aba4532"], "d": ["Տրիպոլիի (Լիբանան) առջև տեղի ունեցած ճակատամարտում Ռեմոն դը Սեն-Ժիլը հաղթեց քաղաքի պաշտպաններին։", "4aba4532"]},
"OLAYLAR_ORTACAG_ORTADOGU:1102-05-22:0":{"b": ["Կարախանյան Հարուն Թեգինը գերի ընկավ Սանջարի ձեռքը և մահապատժի ենթարկվեց. Տերմեզը մնաց Մեծ Սելջուկների ձեռքին", "85927671"], "d": ["Մելիքշահի որդիների միջև խառնաշփոթից օգտվելով Խորասանը գրավել ցանկացող և Տերմեզը զավթած Կարախանյան Հարուն Թեգինը սելջուկ սուլթան Սանջարի կողմից գերի վերցվեց և մահապատժի ենթարկվեց (2 Շաաբան 495 / 1102 թ. մայիսի 22)։ Ատլասում Տերմեզը այս օրվանից վերագրված է Մեծ Սելջուկյան պետությանը. սա իրադարձության եզրահանգումն է (ՀԱՅՏԱՐԱՐՎԱԾ ՄՈՏԱՎՈՐՈՒԹՅՈՒՆ)։", "6a6f35ce"]},
"OLAYLAR_ORTACAG_ORTADOGU:1104-01-01:0":{"b": ["Դուքաքի մահից հետո Ռիդվանը, վերցնելով Դամասկոսը, խուտբա կարդացնել տվեց իր անունով և դրամ հատել տվեց (1104 թ. հունիս)։", "eb80ef6f"], "d": ["Դուքաքի մահից հետո Ռիդվանը, վերցնելով Դամասկոսը, խուտբա կարդացնել տվեց իր անունով և դրամ հատել տվեց (1104 թ. հունիս)։", "eb80ef6f"]},
"OLAYLAR_ORTACAG_ORTADOGU:1104-01-01:1":{"b": ["Գերի Բոհեմունդին փոխարինող Տանկրեդը 1104 թ. Բոհեմունդի Եվրոպա վերադառնալով սկսեց մշտապես կառավարել Անտիոքը։", "39060b18"], "d": ["Գերի Բոհեմունդին փոխարինող Տանկրեդը 1104 թ. Բոհեմունդի Եվրոպա վերադառնալով սկսեց մշտապես կառավարել Անտիոքը։", "39060b18"]},
"OLAYLAR_ORTACAG_ORTADOGU:1104-01-01:2":{"b": ["Ռեմոնը, 1103 թ. դեկտեմբերին քաղաքի արվարձաններում ռազմակայան հիմնելուց հետո, բյուզանդացիների օգնությամբ Տրիպոլիից 5 կմ հեռավորության վրա կառուցել տվեց մեծ աշտարակ. պաշարումը խստացավ։", "6a2f8e1a"], "d": ["Ռեմոնը, 1103 թ. դեկտեմբերին քաղաքի արվարձաններում ռազմակայան հիմնելուց հետո, բյուզանդացիների օգնությամբ Տրիպոլիից 5 կմ հեռավորության վրա կառուցել տվեց մեծ աշտարակ. պաշարումը խստացավ։", "6a2f8e1a"]},
"OLAYLAR_ORTACAG_ORTADOGU:1104-05-07:0":{"b": ["Հառանի ճակատամարտում խաչակիրները պարտվեցին. Բոդուեն դյու Բուրգը և Ժոսլենը գերի ընկան, Ուրֆան անցավ Անտիոքի վերահսկողության տակ։", "792f8e47"], "d": ["Հառանի ճակատամարտում խաչակիրները պարտվեցին. Բոդուեն դյու Բուրգը և Ժոսլենը գերի ընկան, Ուրֆան անցավ Անտիոքի վերահսկողության տակ։", "792f8e47"]},
